import{_ as i,W as o,s as l,u as r,ah as d,I as p,w as n,Z as s,A as t}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const y=JSON.parse('{"title":"机器学习：使用 Python 进行预测 | LCTT x X-CMD","titleTemplate":false,"description":"机器学习：使用 Python 进行预测 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"机器学习：使用 Python 进行预测 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"机器学习：使用 Python 进行预测 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220530 Using a Machine Learning Model to Make Predictions","title":"机器学习：使用 Python 进行预测","tag":"202206"},"relativePath":"202206/20220530 Using a Machine Learning Model to Make Predictions.md","filePath":"[post].md"}'),u={name:"202206/20220530 Using a Machine Learning Model to Make Predictions.md"};function m(g,a,h,c,f,v){const e=o("Link");return r(),l("div",null,[a[20]||(a[20]=d(`<h1 id="机器学习-使用-python-进行预测" tabindex="-1">机器学习：使用 Python 进行预测 <a class="header-anchor" href="#机器学习-使用-python-进行预测" aria-label="Permalink to 机器学习：使用 Python 进行预测">​</a></h1><blockquote><p>机器学习基本上是人工智能的一个子集，它使用以前存在的数据对新数据进行预测。</p></blockquote><p>当然，现在我们所有人都知道这个道理了！这篇文章展示了如何将 Python 中开发的机器学习模型作为 Java 代码的一部分来进行预测。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/05/Machine-learning.jpg" alt="Machine-learning"></p><p>本文假设你熟悉基本的开发技巧并理解机器学习。我们将从训练我们的模型开始，然后在 Python 中制作一个机器学习模型。</p><p>我以一个洪水预测模型为例。首先，导入以下库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import pandas as pd</span></span>
<span class="line"><span>import numpy as np</span></span>
<span class="line"><span>import matplotlib.pyplot as plt</span></span></code></pre></div><p>当我们成功地导入了这些库，我们就需要输入数据集，如下面的代码所示。为了预测洪水，我使用的是河流水位数据集。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>from google.colab import files</span></span>
<span class="line"><span>uploaded = files.upload()</span></span>
<span class="line"><span>for fn in uploaded.keys(): </span></span>
<span class="line"><span>    print(&#39;User uploaded file &quot;{name}&quot; with length {length} bytes&#39;.format(name=fn, length=len(uploaded[fn])))</span></span></code></pre></div><p>如果没有选择文件的话，选择上传的文件。</p><p>只有在当前浏览器会话中执行了该单元格时，上传部件才可用。请重新运行此单元，上传文件 <code>Hoppers Crossing-Hourly-River-Level.csv</code>，大小 2207036 字节。</p><p>完成后，我们就可以使用 <code>sklearn</code> 库来训练我们的模型。为此，我们首先需要导入该库和算法模型，如图 1 所示。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/05/Figure-1Training-the-model.jpg" alt="Figure 1: Training the model"></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>from sklearn.linear_model import LinearRegression</span></span>
<span class="line"><span>regressor = LinearRegression()</span></span>
<span class="line"><span>regressor.fit(X_train, y_train)</span></span></code></pre></div><p>完成后，我们就训练好了我们的模型，现在可以进行预测了，如图 2 所示。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/05/Figure-2-Making-predictions.jpg" alt="Figure 2: Making predictions"></p><h3 id="在-java-中使用-ml-模型" tabindex="-1">在 Java 中使用 ML 模型 <a class="header-anchor" href="#在-java-中使用-ml-模型" aria-label="Permalink to 在 Java 中使用 ML 模型">​</a></h3><p>我们现在需要做的是把 ML 模型转换成一个可以被 Java 程序使用的模型。有一个叫做 <code>sklearn2pmml</code> 的库可以帮助我们做到这一点：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Install the library</span></span>
<span class="line"><span>pip install sklearn2pmml</span></span></code></pre></div><p>库安装完毕后，我们就可以转换我们已经训练好的模型，如下图所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sklearn2pmml(pipeline, ‘model.pmml’, with_repr = True)</span></span></code></pre></div><p>这就完成了！我们现在可以在我们的 Java 代码中使用生成的 <code>model.pmml</code> 文件来进行预测。请试一试吧！</p>`,22)),p("p",null,[a[1]||(a[1]=n("（LCTT 译注：Java 中有第三方库 ")),s(e,{href:"https://github.com/jpmml/jpmml-evaluator"},{default:t(()=>a[0]||(a[0]=[n("jpmml/jpmml-evaluator")])),_:1}),a[2]||(a[2]=n("，它能帮助你使用生成的 ")),a[3]||(a[3]=p("code",null,"model.pmml",-1)),a[4]||(a[4]=n(" 进行预测。）"))]),a[21]||(a[21]=p("hr",null,null,-1)),p("p",null,[a[6]||(a[6]=n("via: ")),s(e,{href:"https://www.opensourceforu.com/2022/05/using-a-machine-learning-model-to-make-predictions/"},{default:t(()=>a[5]||(a[5]=[n("https://www.opensourceforu.com/2022/05/using-a-machine-learning-model-to-make-predictions/")])),_:1})]),p("p",null,[a[11]||(a[11]=n("作者：")),s(e,{href:"https://www.opensourceforu.com/author/jishnu-saurav-mittapalli/"},{default:t(()=>a[7]||(a[7]=[n("Jishnu Saurav Mittapalli")])),_:1}),a[12]||(a[12]=n(" 选题：")),s(e,{href:"https://github.com/lkxed"},{default:t(()=>a[8]||(a[8]=[n("lkxed")])),_:1}),a[13]||(a[13]=n(" 译者：")),s(e,{href:"https://github.com/geekpi"},{default:t(()=>a[9]||(a[9]=[n("geekpi")])),_:1}),a[14]||(a[14]=n(" 校对：")),s(e,{href:"https://github.com/wxy"},{default:t(()=>a[10]||(a[10]=[n("wxy")])),_:1})]),p("p",null,[a[17]||(a[17]=n("本文由 ")),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>a[15]||(a[15]=[n("LCTT")])),_:1}),a[18]||(a[18]=n(" 原创编译，")),s(e,{href:"https://linux.cn/"},{default:t(()=>a[16]||(a[16]=[n("Linux中国")])),_:1}),a[19]||(a[19]=n(" 荣誉推出"))])])}const C=i(u,[["render",m]]);export{y as __pageData,C as default};
